def get_contract_translation(language: str) -> dict:
    """Get contract translation for a language code. Falls back to Estonian."""
    lang = language.lower().replace("-", "_")[:5]
    if lang in CONTRACT_TRANSLATIONS:
        return CONTRACT_TRANSLATIONS[lang]
    short = lang[:2]
    if short in CONTRACT_TRANSLATIONS:
        return CONTRACT_TRANSLATIONS[short]
    return CONTRACT_TRANSLATIONS["et"]
